// Generate a writable temporary file path and open it for text output.
const char *path = FUZZ_PARAM_FILENAME();
FILE *fp = fopen(path, "w");
if (!fp) { FUZZ_BAIL(); }
// Call the target: write version info to the file. We assume it only writes text.
rwpng_version_info(fp);
// Close stream to flush and release OS resources.
fclose(fp);

// Prepare a readable file: FUZZ_PARAM_FILENAME produces a file with random data.
const char *path = FUZZ_PARAM_FILENAME();
FILE *infile = fopen(path, "rb");
if (!infile) { FUZZ_BAIL(); }
// Allocate a png24_image struct that rwpng will populate.
png24_image *img24 = (png24_image*)malloc(sizeof(png24_image));
if (!img24) { fclose(infile); FUZZ_BAIL(); }
// Zero-initialize to ensure rwpng_free_image24 can safely free on success.
memset(img24, 0, sizeof(*img24));
// strip/verbose flags: 0 or 1 to keep behavior simple and constrained.
int strip = (int)(*FUZZ_PARAM(unsigned int) & 1u);
int verbose = (int)((*FUZZ_PARAM(unsigned int) >> 1) & 1u);
// Invoke the target read routine.
pngquant_error st = rwpng_read_image24(infile, img24, strip, verbose);
// Close the input regardless of result.
fclose(infile);
// Enforce that this stub only outputs a valid, populated image object.
if (st != SUCCESS) {
    // Nothing should escape on failure; avoid leaking heap struct.
    // Since the API may have allocated internal buffers only on success,
    // we skip rwpng_free_image24 here and just drop the struct.
    free(img24);
    FUZZ_BAIL();
}
// Success: annotate attributes for downstream stubs (free/write).
FUZZ_SET_ATTR_INT(img24, "alive", 1);
FUZZ_SET_ATTR_INT(img24, "width", (int)img24->width);
FUZZ_SET_ATTR_INT(img24, "height", (int)img24->height);

// Open an output file for binary writing.
const char *outpath = FUZZ_PARAM_FILENAME();
FILE *outfile = fopen(outpath, "wb");
if (!outfile) { FUZZ_BAIL(); }
// Create and initialize a small, valid png8_image for writing.
png8_image *img8 = (png8_image*)malloc(sizeof(png8_image));
if (!img8) { fclose(outfile); FUZZ_BAIL(); }
memset(img8, 0, sizeof(*img8));
// Keep allocations bounded (<2048 bytes) and dimensions reasonable.
unsigned int w = (unsigned int)(*FUZZ_PARAM(unsigned int) % 64u) + 1u;
unsigned int h = (unsigned int)(*FUZZ_PARAM(unsigned int) % 64u) + 1u;
img8->width = w;
img8->height = h;
// Gamma in a typical range [0.1, 4.0]
img8->gamma = ((double)((*FUZZ_PARAM(unsigned int) % 3900u) + 100u)) / 1000.0;
// Compression flag and max file size metadata (unchecked by API here)
img8->fast_compression = (char)((*FUZZ_PARAM(unsigned int)) & 1u);
img8->maximum_file_size = (size_t)((*FUZZ_PARAM(unsigned int) % 2048u) + 1u);
// Choose an output color transform from the enum range [0,6].
img8->output_color = (rwpng_color_transform)((int)(*FUZZ_PARAM(unsigned int) % 7u));
// Allocate indexed pixel buffer and row pointers.
size_t pixels = (size_t)w * (size_t)h;
img8->indexed_data = (unsigned char*)malloc(pixels);
img8->row_pointers = (unsigned char**)malloc(sizeof(unsigned char*) * h);
if (!img8->indexed_data || !img8->row_pointers) {
    if (img8->row_pointers) free(img8->row_pointers);
    if (img8->indexed_data) free(img8->indexed_data);
    free(img8);
    fclose(outfile);
    FUZZ_BAIL();
}
for (unsigned int y = 0; y < h; ++y) {
    img8->row_pointers[y] = img8->indexed_data + (size_t)y * (size_t)w;
}
// Palette: at least 1 entry, up to 256.
unsigned int nplte = (unsigned int)(*FUZZ_PARAM(unsigned int) % 256u) + 1u;
img8->num_palette = nplte;
// Fill palette and pixel data from a random byte stream, cycling as needed.
std::string entropy = FUZZ_PARAM_STR();
if (entropy.size() == 0) entropy = std::string("\x00", 1);
size_t ei = 0, elen = entropy.size();
// Fill palette entries.
for (unsigned int i = 0; i < nplte; ++i) {
    img8->palette[i].r = (unsigned char)entropy[ei]; ei = (ei + 1) % elen;
    img8->palette[i].g = (unsigned char)entropy[ei]; ei = (ei + 1) % elen;
    img8->palette[i].b = (unsigned char)entropy[ei]; ei = (ei + 1) % elen;
    img8->palette[i].a = (unsigned char)entropy[ei]; ei = (ei + 1) % elen;
}
// Fill indexed pixels with palette indices.
for (size_t i = 0; i < pixels; ++i) {
    img8->indexed_data[i] = (unsigned char)(entropy[ei] % nplte);
    ei = (ei + 1) % elen;
}
// No ancillary chunks in this minimal harness.
img8->chunks = NULL;
// Perform the write.
pngquant_error st = rwpng_write_image8(outfile, img8);
// Close file regardless of result.
fclose(outfile);
// We accept both success/failure without bailing, but the object remains valid for reuse/free.
// Mark attributes so free stub knows this object owns allocations.
FUZZ_SET_ATTR_INT(img8, "alive", 1);
FUZZ_SET_ATTR_INT(img8, "width", (int)img8->width);
FUZZ_SET_ATTR_INT(img8, "height", (int)img8->height);

// Open an output file for binary writing.
const char *outpath = FUZZ_PARAM_FILENAME();
FILE *outfile = fopen(outpath, "wb");
if (!outfile) { FUZZ_BAIL(); }
// Create and initialize a small, valid png24_image for writing.
png24_image *img24 = (png24_image*)malloc(sizeof(png24_image));
if (!img24) { fclose(outfile); FUZZ_BAIL(); }
memset(img24, 0, sizeof(*img24));
// Keep image reasonably small.
unsigned int w = (unsigned int)(*FUZZ_PARAM(unsigned int) % 64u) + 1u;
unsigned int h = (unsigned int)(*FUZZ_PARAM(unsigned int) % 64u) + 1u;
img24->width = w;
img24->height = h;
img24->gamma = ((double)((*FUZZ_PARAM(unsigned int) % 3900u) + 100u)) / 1000.0;
img24->input_color = (rwpng_color_transform)((int)(*FUZZ_PARAM(unsigned int) % 7u));
img24->output_color = (rwpng_color_transform)((int)(*FUZZ_PARAM(unsigned int) % 7u));
// Allocate RGBA buffer and row pointers.
size_t rowbytes = (size_t)w * 4u;
size_t bufsize = rowbytes * (size_t)h;
img24->rgba_data = (unsigned char*)malloc(bufsize);
img24->row_pointers = (unsigned char**)malloc(sizeof(unsigned char*) * h);
if (!img24->rgba_data || !img24->row_pointers) {
    if (img24->row_pointers) free(img24->row_pointers);
    if (img24->rgba_data) free(img24->rgba_data);
    free(img24);
    fclose(outfile);
    FUZZ_BAIL();
}
for (unsigned int y = 0; y < h; ++y) {
    img24->row_pointers[y] = img24->rgba_data + (size_t)y * rowbytes;
}
// Fill pixel data from random bytes, cycling as needed.
std::string entropy = FUZZ_PARAM_STR();
if (entropy.size() == 0) entropy = std::string("\x00", 1);
size_t ei = 0, elen = entropy.size();
for (size_t i = 0; i < bufsize; ++i) {
    img24->rgba_data[i] = (unsigned char)entropy[ei];
    ei = (ei + 1) % elen;
}
img24->chunks = NULL;
// Write the image using the const-qualified API.
pngquant_error st = rwpng_write_image24(outfile, (const png24_image*)img24);
// Close file regardless of result.
fclose(outfile);
// As with 8-bit write, keep the object available regardless of status for later freeing.
FUZZ_SET_ATTR_INT(img24, "alive", 1);
FUZZ_SET_ATTR_INT(img24, "width", (int)img24->width);
FUZZ_SET_ATTR_INT(img24, "height", (int)img24->height);

// Only free images that were previously marked alive by read/write stubs.
int alive = FUZZ_GET_ATTR_INT(img24, "alive");
if (!alive) { FUZZ_BAIL(); }
// Invoke the target free routine which releases internal buffers.
rwpng_free_image24(img24);
// Mark as freed to prevent double-free in subsequent stubs.
FUZZ_SET_ATTR_INT(img24, "alive", 0);

// Only free images that were previously marked alive by a write stub.
int alive = FUZZ_GET_ATTR_INT(img8, "alive");
if (!alive) { FUZZ_BAIL(); }
// Invoke the target free routine which releases internal buffers.
rwpng_free_image8(img8);
// Mark as freed to prevent double-free in subsequent stubs.
FUZZ_SET_ATTR_INT(img8, "alive", 0);
